-- Training Provider, System Development, and Technology Provider.
-- INSERT OR IGNORE preserves existing products, SKU references, scope edits, and pricing.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS rti_product_industries (
 product_sku TEXT NOT NULL REFERENCES rti_products(sku) ON DELETE CASCADE,
 industry_code TEXT NOT NULL CHECK (industry_code IN ('FSI','Manufacturing','Government','Other')),
 PRIMARY KEY (product_sku,industry_code)
);
CREATE INDEX IF NOT EXISTS idx_rti_product_industries_sector ON rti_product_industries(industry_code,product_sku);
